Use ASP.NET Core's `WebApplicationFactory<T>` to host your server in-process and send MCP requests via its `HttpClient`:

```csharp
// MyMcpServerTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2025-03-26",
            body.GetProperty("result").GetProperty("protocolVersion").GetString());
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/list",
            @params = new { }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

**Key points:**

- **`WebApplicationFactory<Program>`** boots your app in-memory with the full middleware pipeline — no port binding needed.
- Send JSON-RPC requests to whatever endpoint your MCP server listens on (e.g., `/mcp` or `/sse`).
- Override services in the factory for test doubles:

```csharp
var factory = new WebApplicationFactory<Program>()
    .WithWebHostBuilder(builder =>
    {
        builder.ConfigureServices(services =>
        {
            services.AddSingleton<IMyDependency, FakeDependency>();
        });
    });
```

- For **Streamable HTTP (SSE)** responses, read the stream manually:

```csharp
var response = await _client.SendAsync(request,
    HttpCompletionOption.ResponseHeadersRead);
using var stream = await response.Content.ReadAsStreamAsync();
using var reader = new StreamReader(stream);
// Read SSE events line-by-line
```

This gives you full protocol coverage (initialize → tool calls → notifications) entirely in-process.
